import React from 'react';
import Header from './Header';
import './UserPage.css';
import Footer from './Footer';
import user from './User.jpg'

function User() {
    return(
        <div className='UserPage'>
            <Header/>
            <h1>User Info</h1>
            <table className='Table'>
                    <tr width='100%'></tr>
                    <td className='column1' width='40%'>
                        <div className='Image'>
                            <img src={user} />
                        </div>
                    </td>  
                    <td className='column2' width='60%'>  
                        <div className='About'>
                            <h4>Name: </h4><p>Nithya.P</p>
                            <h4>email adress: </h4><p>123@gmail.com</p>
                            <h4>Password: </h4><p>123456</p>
                        </div>
                    </td>  
            </table>
            <Footer/>
        </div>
    );
}


export default User;
